import { useState } from "react";
import "./Bar.css"
function Bar() {
    const [text, setText] = useState('')
    const handleText = (e) => {
        setText(e.target.value);
    }
    return (
        <input 
            type = "text"
            value = {text}
            onChange = {handleText}
            className = "bar"
            readOnly = "true"/>

    )
}
export default Bar;
